const staticArticleRewritePack = {
  "longterm-care-apply": {
    dek: "第一次接觸長照時，先不用急著背服務名稱；把生活困難說清楚，才是安排服務的起點。",
    content: [
      ["先把問題從「需要照顧」改成「哪裡卡住」", "家人第一次申請長照，常會被補助、失能等級、服務項目弄得很緊張。其實最有幫助的準備，是先寫下長輩每天在哪些動作需要協助，例如起身、洗澡、備餐、吃藥、外出、回診或夜間如廁。問題越具體，後續評估越容易轉成可安排的服務。"],
      ["把家庭能承擔的範圍也說出來", "長照不是只看長輩需要什麼，也要看家屬目前還能做多少。主要照顧者是否要上班、夜裡是否睡不好、家中是否有人能輪替，這些都會影響服務設計。把家屬壓力放進討論，不是抱怨，而是讓照顧計畫更接近真實生活。"],
      ["服務可以先從最急的一段開始", "不需要一次把所有服務都排滿。若最危險的是洗澡，就先談沐浴與浴室安全；若白天沒人陪，就先評估日照或社區據點；若剛出院，就先把用藥、復能和照顧紀錄接上。長照申請是一段調整過程，不是一次考試。"]
    ]
  },
  "family-care-story": {
    dek: "出院後最難的不是把人接回家，而是每天都知道該觀察什麼、什麼時候要調整。",
    content: [
      ["回家第一週，家屬最怕漏掉重要變化", "林小姐說，爸爸出院時拿了一疊藥單和注意事項，但真正回到家後，家人最不安的是每天不知道哪些反應正常、哪些變化需要求助。歲悅進場後，先把用餐、用藥、精神、移位和疼痛整理成每日觀察重點，讓家屬終於有可以依循的方向。"],
      ["紀錄讓照顧不再只靠口頭交代", "每次服務後，照服員會留下今天的照顧狀況，包含吃了多少、走路穩不穩、情緒如何、家中動線是否有風險。這些紀錄讓下班後的家人能快速接上，而不是一直打電話追問或靠記憶拼湊。"],
      ["真正安心的是背後有團隊一起看", "當爸爸狀態改變，現場照服員會回報督導，督導再和家屬討論是否調整服務方式或串接其他資源。林小姐最有感的是，照顧不再像家人自己在黑暗中摸索，而是有人一起把每天的變化接住。"]
    ]
  },
  "master-talk-care-psychology": {
    dek: "照顧心理講師周小姐提醒，照顧品質不只看服務完成，也要看家庭是否還能好好生活。",
    content: [
      ["家屬的煩躁，很多時候是壓力太久沒有出口", "周小姐觀察，家屬常把自己的疲憊解讀成不夠孝順，但長期照顧原本就會消耗睡眠、工作、情緒和家庭關係。當所有決定都落在同一個人身上，焦慮和煩躁就很容易變成日常。"],
      ["照顧建議要變成今天做得到的事", "家庭需要的不是一大堆專業名詞，而是清楚知道今天先處理什麼。比如先固定用藥提醒、先把浴室動線整理好、先安排一段喘息服務。能被執行的建議，才會讓家屬感覺被支持。"],
      ["生活感不是奢侈，是照顧能持續的條件", "好的照顧不該把家變成病房。長輩仍然可以有偏好、選擇和熟悉的節奏；家屬也需要工作、休息和自己的生活。照顧系統的目的，是讓安全和生活能同時存在。"]
    ]
  },
  "safe-transfer-tips": {
    dek: "起身不是用力拉起來，而是讓長輩先找到腳、手和重心的位置。",
    content: [
      ["起身前先看環境，不是先伸手拉人", "床太低、椅子太軟、腳踩不到地，長輩就很難安全起身。照顧者協助前，先確認雙腳能踩穩，旁邊有固定扶手或穩定支撐，地面沒有拖鞋、電線或滑動地墊。"],
      ["讓長輩參與動作，身體才不會被拉歪", "直接拉手臂容易讓肩膀受傷，也會把長輩重心拉離身體。比較安全的方式，是用簡短口令提醒：腳收回、身體往前、手扶穩、再慢慢站。照顧者在旁邊保護，而不是代替長輩用力。"],
      ["站起來不是結束，穩住才算完成", "剛站起來時，長輩可能頭暈、腳軟或還沒抓到平衡。建議先站著停幾秒，確認表情、呼吸和腳步穩定，再開始轉身或走路。把這個停頓變成習慣，能降低很多跌倒風險。"]
    ]
  },
  "nutrition-warning": {
    dek: "長輩吃得少，可能是牙口、吞嚥、藥物、情緒或疾病變化一起造成的結果。",
    content: [
      ["先分辨是偶爾少吃，還是狀態正在下降", "一兩餐胃口差不一定嚴重，但如果連續幾天吃得少、衣服變鬆、起身變慢、白天嗜睡，就不能只說是老化。家屬可以用一週紀錄看趨勢，而不是每天在餐桌上追著問。"],
      ["吃不下常常不是單一原因", "牙齒痛、假牙不合、吞嚥不順、藥物副作用、便秘、憂鬱、活動量下降，都可能讓長輩不想吃。把剩下哪些食物、吃飯花多久、喝水會不會咳記下來，後續諮詢會更有效。"],
      ["餐食調整要做得到，才會持續", "與其立刻大改菜單，不如先調整質地、份量、用餐時間和水分補充方式。若合併體重下降、反覆嗆咳或精神明顯變差，應及早尋求醫療、營養或照顧團隊協助。"]
    ]
  },
  "dementia-response": {
    dek: "反覆提問背後常是安全感不足；先讓長輩安定，再回答問題。",
    content: [
      ["不要急著證明答案是對的", "失智長輩重複問同一題時，家屬很容易越回答越急。但長輩需要的常不是新答案，而是再次確認自己安全、有人在、下一步不會失控。先接住情緒，衝突會少很多。"],
      ["建立家裡共同使用的固定說法", "例如「你今天在家，晚餐後我們休息」、「車子下午會送你回來」、「我陪你看一下」。同一句話重複使用，比每次換不同解釋更容易被理解，也能讓不同家人接手。"],
      ["讓提示物幫家人分擔壓力", "白板、照片、日曆、門牌、固定位置的包包或水杯，都能提供線索。環境能說明一部分事情，照顧者就不必一直用情緒回答同一個問題。"]
    ]
  },
  "caregiver-support": {
    dek: "照顧者不是不夠努力，而是需要把責任拆開，讓服務和家人一起接住。",
    content: [
      ["先承認你已經很累", "主要照顧者常把疲憊藏起來，直到失眠、易怒、身體疼痛或工作受影響才發現自己快撐不住。照顧累不是不孝，而是照顧工作真的太密、太長、太少人分擔。"],
      ["用時段拆解壓力", "不要只說整天都累，先寫下最卡的時段：洗澡、夜間如廁、備餐、回診、下班後交接。當困難變成具體時段，就比較能討論居家照顧、日照、喘息或家人輪替。"],
      ["讓主要照顧者也被照顧", "一個家庭要走得久，不能只看長輩有沒有被照顧，也要看照顧者有沒有休息、睡眠和求助窗口。服務介入不是把責任丟出去，而是讓照顧關係不被壓垮。"]
    ]
  },
  "family-care-course": {
    dek: "家屬課不是聽一堆理論，而是把家裡每天會遇到的照顧動作練到可操作。",
    content: [
      ["家屬最需要的是可上手的方法", "很多家人照顧長輩，是在壓力中邊做邊學。課程會把常見照顧動作拆成家屬聽得懂的步驟，像是如何扶起、如何提醒吃藥、如何觀察嗆咳與跌倒風險。"],
      ["用家裡會發生的情境練習", "照顧技巧如果離生活太遠，回家就用不上。課程會以浴室、床邊、餐桌、夜間如廁等情境設計，讓家屬知道在有限空間和有限人力下可以怎麼做。"],
      ["學會之後，還要知道何時求助", "課程不是要家屬包辦所有事，而是幫助家屬分辨哪些能自己做、哪些需要專業介入。當風險升高時，可以銜接居家照顧、復能、日照或督導諮詢。"]
    ]
  },
  "day-care-respite": {
    dek: "日照不是把長輩送走，而是讓白天有節奏、有人陪、家屬也能喘一口氣。",
    content: [
      ["日照的一天，要看得見照顧邏輯", "參觀日不只是看空間漂亮不漂亮，也要看長輩進出動線、廁所位置、活動安排、餐食照顧、午休方式和緊急應變。這些細節決定長輩每天來是否安心。"],
      ["白天有陪伴，晚上仍回到熟悉的家", "日間照顧能讓長輩維持社交和活動，也讓家屬白天可以工作、休息或處理其他責任。對許多家庭來說，這是一種不把長輩完全離開家的照顧平衡。"],
      ["參觀時也要問回報怎麼做", "家屬需要知道今天吃得如何、活動參與如何、精神和情緒是否穩定。好的日照服務不只照顧現場，也會讓家庭接得上長輩回家後的狀態。"]
    ]
  },
  "reablement-workshop": {
    dek: "復能的目的不是把動作做漂亮，而是讓長輩重新對生活動作有把握。",
    content: [
      ["復能要先問生活目標", "長輩想要的可能不是多走幾公尺，而是能自己走到餐桌、到浴室、出門曬太陽。工作坊會把復能目標放回生活任務，讓練習變得有意義。"],
      ["小步驟比大目標更能累積信心", "站起、扶穩、轉身、走幾步，每個動作都可以拆開練。當長輩感覺自己做得到，就比較願意持續，而不是因為一次失敗就放棄。"],
      ["家屬也要知道怎麼陪", "家屬不是治療師，但可以學會安全站位、口令、觀察疲累和避免硬拉。當家裡每天的陪伴方式正確，復能才不會只停留在課堂。"]
    ]
  },
  "fall-observation": {
    dek: "跌倒後不要只看有沒有流血，意識、疼痛、走路和精神變化都需要追蹤。",
    content: [
      ["跌倒當下先停一下，不要急著扶起", "如果長輩說痛、頭暈、撞到頭或無法清楚回答，先不要硬拉起來。確認意識、呼吸、疼痛位置和是否有明顯變形，比立刻站起來更重要。"],
      ["接下來一天要看變化", "有些頭部撞擊、肌肉拉傷或骨折不是當下最明顯。家屬要留意頭痛、嘔吐、嗜睡、走路不穩、情緒改變、食慾下降或疼痛加劇。"],
      ["跌倒後的重點是避免下一次", "處理完當下狀況後，要檢查光線、拖鞋、地墊、浴室、床邊高度、用藥和夜間如廁路線。每一次跌倒都是一次重新檢視環境和照顧流程的提醒。"]
    ]
  },
  "bathroom-safety": {
    dek: "浴室安全不是裝一支扶手就好，而是看長輩從進門到擦乾的每一步。",
    content: [
      ["先從進出浴室那一步看起", "浴室門口、門檻、地墊和積水處，是很多跌倒發生的位置。長輩不是只在洗澡時會滑倒，也可能在跨進、跨出或轉身拿毛巾時失去平衡。"],
      ["設備要放在用得到的位置", "扶手、淋浴椅、防滑墊和置物架都要配合長輩動作。若扶手裝太遠、椅子不穩或用品放太高，照顧者還是會在現場臨時補救，風險不會真的下降。"],
      ["洗澡後也要觀察身體反應", "洗澡容易耗體力，也可能因水溫、站立或悶熱造成頭暈。洗完後先坐一下、擦乾保暖、觀察臉色和呼吸，是浴室安全流程的一部分。"]
    ]
  },
  "master-talk-senior-nutrition": {
    dek: "銀髮營養顧問李先生提醒，餐盤只是線索，真正要看的是體力和生活變化。",
    content: [
      ["不要只問今天吃幾口", "李先生說，長輩的營養狀態常常先反映在生活裡：走路變慢、起身變吃力、白天更累、衣服變鬆。餐盤上的份量重要，但不能單獨解讀。"],
      ["找出吃不下背後的原因", "牙口、吞嚥、便秘、藥物、情緒、活動量和用餐環境都會影響食慾。家屬可以先記錄一週，觀察哪些食物剩最多、哪個時段吃得比較好。"],
      ["營養建議要讓家庭做得到", "高標準菜單如果準備不了，很快就會中斷。從質地、少量多餐、水分補充和長輩喜歡的味道開始，往往比一次大改更能持續。"]
    ]
  },
  "master-talk-rehab-goals": {
    dek: "復能治療師許小姐談的不是訓練口號，而是長輩想重新完成的生活動作。",
    content: [
      ["復能先從生活願望開始", "許小姐分享，長輩願意練習，常常不是因為想達成某個數字，而是想自己走到廁所、坐到餐桌、和家人出門。復能目標越貼近生活，越容易被理解。"],
      ["把動作拆小，挫折就會少一點", "站起來可以拆成坐到床緣、腳踩穩、身體前傾、手扶好、慢慢站。當每一步都能完成，長輩會比較有信心，而不是覺得自己一直失敗。"],
      ["家屬要學會保護而不是催促", "陪練時最重要的是安全站位、清楚口令和觀察疲累。催快一點通常沒有幫助，穩定陪伴反而能讓長輩願意多試一次。"]
    ]
  },
  "master-talk-home-safety": {
    dek: "居家安全顧問張先生提醒，最熟悉的路線，往往最容易被忽略。",
    content: [
      ["危險常藏在每天經過的地方", "張先生看過很多家庭，客廳很整齊，但床邊到浴室卻有地墊、延長線和昏暗轉角。因為每天都走，家人反而習慣了風險。"],
      ["先選一條路線做完整檢查", "不必一開始就全面翻修。先陪長輩從床邊走到浴室，觀察哪裡需要扶、哪裡會轉身、哪裡需要跨過、哪裡看不清楚。改好一條高頻路線，就能先降一大段風險。"],
      ["安全設備要讓長輩願意用", "扶手位置、防滑墊材質、椅子高度和夜燈亮度，都要依長輩動作調整。買了設備卻不符合習慣，最後仍會回到原本高風險的做法。"]
    ]
  },
  "master-talk-care-management": {
    dek: "照顧管理專家陳小姐說，照顧要先變成可分工的計畫，才不會只靠一個人硬撐。",
    content: [
      ["照顧最難的是責任沒有邊界", "陳小姐觀察，家庭常說大家都會幫忙，但真正出事時還是落在主要照顧者身上。照顧需要被拆成明確任務，包含誰負責、什麼時段、做到什麼程度。"],
      ["喘息不是補救，而是預防", "等到家屬崩潰才安排服務，通常已經傷到家庭關係。若能提早把日照、居家照顧、短暫喘息或家人輪替放進計畫，照顧比較能長期維持。"],
      ["紀錄讓家庭不必一直重問", "服務紀錄、用藥紀錄和異常提醒，能讓不同家人站在同一頁。資訊清楚，爭執就會少一點，照顧決策也會更有依據。"]
    ]
  },
  "master-talk-dementia-care": {
    dek: "失智照顧講師林先生提醒，重複提問不是故意，而是長輩正在尋找安全感。",
    content: [
      ["問題反覆出現，通常是安全感反覆掉線", "林先生說，失智長輩可能忘記剛剛得到的答案，但不安的感覺還在。家屬若一直糾正，很容易讓長輩更焦慮，也讓自己更疲憊。"],
      ["先穩住情緒，再給簡短答案", "可以先說「我在這裡」、「你現在很安全」，再用固定短句說明下一步。越複雜的解釋，越可能讓長輩抓不到重點。"],
      ["把照顧壓力分散出去", "當同一個問題一天出現很多次，家屬需要的不只是技巧，也需要有人輪替、日照活動或居家服務協助。照顧者能休息，回應才有餘裕。"]
    ]
  },
  "master-talk-nursing-observation": {
    dek: "護理照護顧問黃小姐說，日常觀察不是緊張兮兮，而是讓變化更早被看見。",
    content: [
      ["身體變化常先藏在日常裡", "黃小姐提醒，長輩可能不是突然生病，而是先出現食慾下降、睡不好、走路變慢、皮膚發紅或白天更累。這些小變化如果被記下來，就能早一點處理。"],
      ["不要被單次數字嚇到，也不要忽略連續變化", "血壓、體溫或血糖一次異常不一定代表嚴重，但如果連續幾天都和平常不同，就需要提高警覺。觀察重點是趨勢和伴隨症狀。"],
      ["紀錄是交接，也是照顧品質", "家屬、照服員、督導和醫療人員若看得到同一份紀錄，就不必每次從頭問起。簡單寫下日期、狀況、處理方式和是否改善，就能讓照顧更穩。"]
    ]
  },
  "master-talk-family-communication": {
    dek: "家庭溝通講師吳先生指出，很多照顧衝突不是不愛，而是責任和期待沒有說清楚。",
    content: [
      ["最累的人常常也是最不敢開口的人", "吳先生分享，主要照顧者常覺得自己說出口就像在抱怨，但不說清楚，其他家人也不知道真正需要什麼。照顧分工要被說出來，才有機會被承擔。"],
      ["家庭會議要具體到可以執行", "比起討論誰比較孝順，更有用的是列出回診、費用、夜間照顧、採買、服務聯絡和緊急決策。每一項都要有人負責，並設定多久回頭檢查。"],
      ["把外部服務當成共同工具", "居家照顧、日照、復能和課程不是某一位家屬的選擇，而是整個家庭的支援系統。當家人都理解服務內容，照顧分工就比較不會變成互相指責。"]
    ]
  },
  "master-talk-community-health": {
    dek: "社區健康推廣鄭小姐談的不是熱鬧活動，而是讓長輩重新有被邀請出門的理由。",
    content: [
      ["長輩需要一個被期待的地方", "鄭小姐說，許多長輩不是完全不想出門，而是不知道去哪裡、誰在等他、去了能做什麼。固定活動和熟悉人群，能讓生活重新有節奏。"],
      ["共餐是很自然的照顧入口", "一起吃飯不只是營養，也包含社交、情緒和觀察。當工作人員熟悉長輩，就比較容易看見食慾、精神或行動能力的變化。"],
      ["社區支持能減少家庭孤立", "家屬如果只有自己在看長輩狀態，壓力會很大。社區據點提供另一組穩定眼睛和陪伴，讓家庭知道有人一起留意。"]
    ]
  },
  "master-talk-longterm-policy": {
    dek: "長照政策觀察王先生提醒，資源再多，如果家庭不知道下一步，就很難真正開始。",
    content: [
      ["家屬需要的是路線圖", "王先生說，長照資源很多，但家庭在壓力中最想知道的是：現在先找誰、先準備什麼、哪一種服務能解決眼前問題。沒有路線圖，資源再多也像迷宮。"],
      ["用情境來理解服務，比背名詞更有效", "如果困難是白天無人陪伴，就談日照或社區；如果是洗澡和備餐，就談居家照顧；如果是剛出院，就談復能、護理和紀錄。服務要從生活問題翻譯出來。"],
      ["好的服務會持續接下一步", "家庭需求會改變，長輩狀態也會變。真正有用的長照支持，不只是一次介紹，而是有人定期追蹤、調整和提醒下一個可用資源。"]
    ]
  },
  "master-talk-medication-safety": {
    dek: "藥事照護顧問蔡藥師提醒，用藥安全的重點不是吃完，而是吃對、看懂、能交接。",
    content: [
      ["先讓藥物資訊集中", "蔡藥師說，很多家庭的藥分散在藥袋、抽屜、不同醫院和不同家人記憶裡。要降低錯誤，第一步是把藥名、用途、時間和劑量整理成同一份清單。"],
      ["不要只確認有沒有吃", "頭暈、嗜睡、食慾變差、便秘、皮膚疹或跌倒，都可能和用藥變化有關。家屬若能記錄吃藥後的反應，回診時就能更精準地討論。"],
      ["用藥流程要能被下一個人接手", "如果只有主要照顧者知道怎麼吃藥，風險就集中在一個人身上。藥盒、提醒、紀錄和回診問題應放在同一套流程裡，讓家人與照顧團隊都能接上。"]
    ]
  },
  "master-talk-frailty-prevention": {
    dek: "失能預防教練郭教練提醒，最好的照顧常常是在退化還沒變嚴重前就開始。",
    content: [
      ["退化通常不是一天發生的", "郭教練說，家屬常在跌倒或住院後才發現長輩變弱，但其實訊號很早就出現：不想出門、走路變慢、起身要扶、容易累。"],
      ["把練習放進每天會做的事", "不一定要安排正式運動，安全起身、短距離走路、站立平衡、餐前伸展和規律出門，都能成為保留生活力的練習。"],
      ["預防的目的，是讓長輩少失去一點", "保留能力不是追求年輕，而是讓長輩還能選擇自己想做的事。越早看見衰弱，越有機會把照顧從補救變成支持。"]
    ]
  },
  "master-talk-swallowing-care": {
    dek: "吞嚥照護語言治療師何小姐提醒，吃得安心，比硬是吃很多更重要。",
    content: [
      ["嗆咳是身體給的提醒", "何小姐說，長輩吃飯喝水常咳、清喉嚨變多、聲音濕濕的，或吃完容易累，這些都不該只用吃太快解釋。"],
      ["用餐安全從姿勢開始", "坐直、腳踩穩、頭頸不後仰，能讓吞嚥比較安全。照顧者也要避免一口接一口催促，應讓長輩吞完再給下一口。"],
      ["質地調整不要全靠猜", "把食物打泥或加稠不一定適合每個人。若嗆咳頻繁、體重下降或反覆發燒，建議記錄狀況並尋求醫療、語言治療或營養專業評估。"]
    ]
  },
  "master-talk-sleep-rhythm": {
    dek: "睡眠照顧諮詢師曾小姐提醒，夜裡不穩，常常會拖垮白天所有照顧。",
    content: [
      ["夜裡的問題，常從白天開始", "曾小姐說，日夜顛倒、半夜頻繁起身，常和白天活動量、午睡長度、光線、晚間飲水和用藥有關。只處理晚上，常常不夠。"],
      ["先把夜間跌倒風險降下來", "床邊夜燈、止滑鞋、通往廁所的路線、扶手位置和常用物品，都要固定。夜間照顧不只關於睡眠，也關於安全。"],
      ["家屬也要有睡覺的權利", "主要照顧者長期睡不好，白天就更難判斷和溝通。日照、居家服務、家人輪替或喘息安排，都可以放進夜間照顧計畫。"]
    ]
  },
  "master-talk-care-subsidy": {
    dek: "長照補助顧問楊先生提醒，費用說清楚，家庭才敢安心開始安排。",
    content: [
      ["家庭害怕的是不確定", "楊先生說，很多家屬不是完全不願意花錢，而是不知道會花多少、補助能用在哪裡、自費會不會越滾越多。資訊不清楚，就很難做決定。"],
      ["服務組合要回到最痛的時段", "補助不是拿滿就好，而是要用在真正減壓的地方。洗澡、備餐、日照、復能、接送或喘息，都應依家庭最困難的情境安排。"],
      ["費用透明是信任的一部分", "好的服務窗口會先說明哪些可補助、哪些需自費、可能頻率和替代方案。當家人都看懂，照顧安排就比較不容易變成爭吵。"]
    ]
  },
  "master-talk-careworker-training": {
    dek: "照服員培訓講師蘇小姐說，專業不只在技術，也在每一次靠近長輩的方式。",
    content: [
      ["照顧品質從第一句話開始", "蘇小姐分享，照服員進門如何問候、是否先告知下一步、是否尊重長輩習慣，都會影響服務能不能順利進行。專業不是冷冰冰，而是穩定而有界線。"],
      ["越高風險，越需要標準流程", "移位、沐浴、翻身、餵食都不能只靠經驗。環境確認、口令、支撐位置、長輩反應和事後紀錄，都需要被訓練和督導追蹤。"],
      ["紀錄讓訓練不只停在課堂", "服務紀錄可以看見現場問題，也能回頭調整教材和督導方式。好的培訓，是把每一次服務經驗轉成下一次更穩的照顧。"]
    ]
  },
  "master-talk-care-technology": {
    dek: "科技照顧產品經理賴先生提醒，系統的價值不是取代照顧，而是讓資訊不斷線。",
    content: [
      ["資訊最容易斷在交接那一刻", "賴先生說，長照服務有很多角色：家屬、照服員、督導、行政和專業人員。若所有資訊都靠口頭轉述，吃飯、用藥、活動和異常狀況很容易漏掉。"],
      ["系統要把複雜變簡單", "家屬不需要看一堆後台欄位，而是要快速知道今天狀況如何、是否有提醒、下次要注意什麼。好的系統會把照顧資訊整理成可以理解的訊號。"],
      ["資料累積後，品質才有辦法追蹤", "當紀錄不再散在 LINE、紙本和口頭交代裡，督導就能看趨勢、找出重複問題、回到訓練和服務調整。系統不是讓人更忙，而是讓照顧更穩。"]
    ]
  }
};

