        citation: "Reddy, M., Gill, S. S., & Rochon, P. A. (2006). Preventing pressure ulcers: A systematic review. JAMA, 296(8), 974-984. https://doi.org/10.1001/jama.296.8.974",
        url: "https://pubmed.ncbi.nlm.nih.gov/16926357/"
