      ["正式開始前，先讓環境變熟悉", ["安排參觀時，不只看設備，也要帶長輩認識廁所、休息區、用餐位置和主要照顧人員。這些細節比家屬想像中更能降低焦慮。", "如果長輩願意，可以先參與短時間活動或共餐。不要一開始就用整天行程測試耐受度。"]],
      ["用固定接送建立可預期感", ["每天出門前用同一句話說明：「今天去中心吃午餐、做活動，下午車子送你回家。」語句固定，比每次換說法更容易讓長輩理解。", "回家時間也很重要。前期若長輩一直問何時回家，可以用簡單時鐘、照片或固定短句協助提醒。"]],
      ["回家後先聽感受，不急著說服", ["長輩說不想去時，先問最不舒服的是什麼：人太多、餐點不習慣、怕找不到家人、不想午休、活動太難。知道原因後，中心才有機會調整。", "家屬也可以觀察回家後精神、食慾、睡眠和情緒是否變化。有些長輩嘴上說不要，身體狀態卻因規律活動慢慢改善。"]],
      ["家屬需要穩定回報，才敢放心", ["日照不是送去就結束。家屬需要知道今天有沒有吃、活動參與如何、情緒如何、是否有特殊狀況。回報越清楚，家屬越能一起協助長輩適應。", "若前兩週有波動，請和中心討論，而不是立刻判斷失敗。照顧轉換需要時間，也需要家庭和團隊一起調整。"]]
