      ["用餐前先確認坐姿與清醒程度", ["長輩要盡量坐直，腳能踩穩，頭頸不要過度後仰。若長輩很想睡、喘、意識不清或一直咳，先不要勉強餵食。", "餐具高度、桌面距離、照顧者站位也會影響安全。照顧者若一直從側邊急著餵，長輩容易來不及準備吞嚥。"]],
      ["一口一口慢慢來，比一直鼓勵多吃更重要", ["每一口份量要小，吞完再下一口。吃飯時避免邊吃邊說話，也不要一直混合湯、水、飯、藥一起入口。", "如果某類食物特別容易嗆，例如水、湯、乾飯、肉塊，要記錄下來。專業人員需要知道是哪些質地出問題。"]],
      ["不要自行亂改成泥狀或濃稠", ["有些家庭會把所有食物打成泥，或自行加稠，覺得這樣比較安全。但不同吞嚥問題需要不同質地，過度簡化可能影響營養和進食意願。", "若嗆咳頻繁，建議尋求醫療、語言治療或營養專業評估，再決定食物質地、姿勢和餵食方式。"]],
      ["把用餐觀察變成照顧紀錄", ["記錄吃了多少、喝水是否咳、吃飯時間、精神狀態、是否發燒或體重下降。這些資訊能讓家屬、照服員和專業人員更快判斷風險。", "如果家庭照顧壓力很高，也可以透過居家照顧或日照共餐協助觀察，讓用餐安全不只靠一位家屬獨自承擔。"]]
